mapper.sql:
(analysis.lease_until IS NULL OR analysis.lease_until < #{now})
AND (
    analysis.program_fingerprint <> 
    OR (analysis.status = 'PENDING' AND analysis.attempt_count < #{maxAttempts})
    OR (analysis.status = 'FAILED' AND analysis.attempt_count < #{maxAttempts}
        AND analysis.next_attempt_at <= #{now})
    OR (analysis.status = 'COMPLETED' AND analysis.analysis_version <> #{expectedVersion}
        AND (analysis.attempt_count = 0
            OR (analysis.attempt_count < #{maxAttempts} AND analysis.next_attempt_at <= #{now})))
)

mapper.select:
SELECT COUNT(*)
FROM support_program_analysis
WHERE last_attempt_at >= #{since}

mapper.update:
UPDATE support_program_analysis
SET next_attempt_at = #{nextAttemptAt,jdbcType=TIMESTAMP},
    lease_token = NULL,
    lease_until = NULL,
    updated_at = #{now}
WHERE source_code = #{sourceCode}
  AND source_program_id = #{sourceProgramId}
  AND status = 'COMPLETED'
  AND lease_token = #{leaseToken}

UPDATE support_program_analysis
SET status = 'FAILED',
    analysis_json = NULL,
    failure_code = #{failureCode},
    next_attempt_at = #{nextAttemptAt,jdbcType=TIMESTAMP},
    lease_token = NULL,
    lease_until = NULL,
    updated_at = #{now}
WHERE source_code = #{sourceCode}
  AND source_program_id = #{sourceProgramId}
  AND lease_token = #{leaseToken}
